window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cc5814ea2c90d29f"]={"versions": [{"id": "FIG-cc5814ea2c90d29f", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Technisches Architektur- und Interaktionsdiagramm (Mischform aus AUTOSAR-Schichtenmodell, Funktions- und PDU-Datenfluss sowie Kontrollfluss zur Dienstverwaltung).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Kopplung zwischen signalbasierter Legacy-Kommunikation (z. B. CAN/LIN/FlexRay) und serviceorientierter Ethernet-Kommunikation (SOME/IP). Dargestellt wird die signal-zu-dienst-übersetzende Software-Komponente (<strong>Translation SWC</strong>) sowie deren Interaktion mit dem <strong>Basic Software Manager (BswM)</strong>, dem <strong>SOME/IP Service Discovery (SD)</strong> und dem <strong>PduR-Routingpfad-Management</strong> zur kontrollierten Dienstfreigabe.\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (R19-11, R20-11, TPS_SystemTemplate). Verortung an der Grenze zwischen VFB/RTE-Ebene (Applikation/Translation SWC, Transformer) und BSW-Kommunikationsstack (<code>LdCom</code>, <code>PduR</code>, <code>SoAd</code>, <code>SD</code>, <code>BswM</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Software-Komponenten &amp; VFB (Applikationsebene)</h5>\n<ul class=\"fig-list\"><li><strong>Translation SWC</strong> (<code>AtomicSwComponentType</code>):\n<ul class=\"fig-list\"><li><strong>R-Ports</strong> (<code>RPortPrototype</code>): Empfang signalbasierter Eingangs-PDUs (<code>PDU [A | C]</code> und <code>PDU [B]</code>).\n</li><li><strong>P-Port (Data)</strong> (<code>PPortPrototype</code>): Typisiert durch <code>SenderReceiverInterface ifZ</code> mit den Datenelementen <code>dataZ1 {A, C}</code> und <code>dataZ2 {B}</code>.\n</li><li><strong>P-Port (Control)</strong> (<code>PPortPrototype</code>): Meldet Dienstverfügbarkeit (<code>Service available</code>) an das BSW.\n</li></ul>\n</li><li><strong>Serializer Transformer</strong> (<code>TransformationTechnology</code>, SOME/IP-Transformer):\n<ul class=\"fig-list\"><li>Arbeitet in der RTE-Transformatorkette.\n</li><li>Serialisiert strukturierte Daten (<code>dataZ1</code>) und stellt den 16-Byte <strong>SOME/IP-Header</strong> voran.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Basis-Software-Module (BSW)</h5>\n<ul class=\"fig-list\"><li><strong>BswM</strong> (<em>Basic Software Manager</em>):\n<ul class=\"fig-list\"><li>Empfängt Statusinformationen über <code>BswMModeRequestPort</code> bzw. BSW-Service-Schnittstelle.\n</li><li>Evaluiert Arbitrierungsregeln (<code>BswMRule</code>) zur Dienstaktivierung.\n</li></ul>\n</li><li><strong>SD</strong> (<em>SOME/IP Service Discovery</em>):\n<ul class=\"fig-list\"><li>Verwaltet den Server-Dienstzustand (<code>SdServerServiceInstance</code>).\n</li><li>Triggert PduR-Routing-Freigabe und sendet SD-Offer-Nachrichten.\n</li></ul>\n</li><li><strong>LdCom</strong> (<em>Large Data Communication</em>):\n<ul class=\"fig-list\"><li>Schlankes Kommunikationsmodul für große, bereits serialisierte PDUs (Umgehung des klassischen COM-Signalpackens).\n</li></ul>\n</li><li><strong>PduR</strong> (<em>PDU Router</em>):\n<ul class=\"fig-list\"><li>Leitet I-PDUs zwischen Quell- und Zielmodulen (<code>LdCom</code> → <code>SoAd</code>).\n</li><li>Besitzt dynamisch schaltbare Routingpfade (<code>PduRRoutingPathGroup</code>).\n</li></ul>\n</li><li><strong>SoAd</strong> (<em>Socket Adaptor</em>):\n<ul class=\"fig-list\"><li>Schnittstelle zum TCP/IP-Stack; zuständig für Socket-Verwaltung, PDU-Fan-out und Protokollkapselung (z. B. <code>Message Length</code> Header).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">PDU- und Nachrichtenstrukturen</h5>\n<ul class=\"fig-list\"><li><strong>Signal-PDUs:</strong> Klassische Payload ohne SOME/IP-Framing (<code>[ A | C ]</code>, <code>[ B ]</code>).\n</li><li><strong>Transformierte I-PDU:</strong> <code>[ SOME/IP Header | A | C ]</code> (am Ausgang des Transformers und durch <code>LdCom</code>/<code>PduR</code>).\n</li><li><strong>Egress-Ethernet-PDU (Data):</strong> <code>[ Message Length | SOME/IP Header | A | C ]</code> (via <code>SoAd</code>).\n</li><li><strong>Egress-Ethernet-PDU (SD):</strong> <code>[ Message Length | SOME/IP Header | SD Payload ]</code> (SD Offer Service Message).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei synchron/asynchron gekoppelte Pfade: Kontrollpfad (Dienstverfügbarkeit) und Datenpfad (Payload-Übertragung).</p>\n<pre class=\"fig-pre\"><code>[Signal-PDUs] ---&gt; (Translation SWC) ---[Service available]---&gt; (BswM)\n                         |                                         |\n                         | (dataZ1)                             (offer)\n                         v                                         v\n                [Serializer Transf.]                              (SD)\n                         |                                      /      \\\n                      (LdCom)                     (enableRouting)     [SD Offer]\n                         |                              |                  |\n                         +-----&gt; (PduR [gesperrt -&gt; AKTIV])              (SoAd)\n                                       |                                   |\n                                    (SoAd)                            [ETH TX]\n                                       |\n                                    [ETH TX]</code></pre>\n<ol class=\"fig-list\"><li><strong>Signal-Empfang &amp; Aggregation:</strong> Die Translation SWC empfängt signalbasierte PDUs über klassische Busse, extrahiert die Signale <code>A</code> und <code>C</code> und aggregiert sie in <code>dataZ1</code>.\n</li><li><strong>Dienstzustandsprüfung:</strong> Sobald die Signale gültig und konsistent vorliegen, setzt die Translation SWC das Kontrollsignal <code>Service available</code> (synchroner RTE-Call / BswM-Port).\n</li><li><strong>BswM-Arbitrierung &amp; SD-Trigger:</strong>\n<ul class=\"fig-list\"><li><code>BswM</code> wertet die Bedingung aus.\n</li><li><code>BswM</code> führt eine Action-List aus und ruft <code>Sd_ServerServiceSetState(..., SD_SERVER_SERVICE_AVAILABLE)</code> auf (<strong>offer</strong>).\n</li></ul>\n</li><li><strong>PduR-Routingpfad-Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Das SD-Modul ruft <code>PduR_EnableRouting()</code> für die referenzierte <code>PduRRoutingPathGroup</code> auf (<strong>enableRouting</strong>).\n</li><li>Erst hierdurch wird der Routing-Pfad in <code>PduR</code> von <em>disabled</em> auf <em>enabled</em> geschaltet. Daten-PDUs vor diesem Zeitpunkt werden verworfen.\n</li></ul>\n</li><li><strong>Dienstpublikation (SOME/IP-SD):</strong>\n<ul class=\"fig-list\"><li>Parallel/unmittelbar folgend übergibt <code>SD</code> die Offer-Service-PDU an <code>SoAd</code>.\n</li><li><code>SoAd</code> sendet <code>[ Message Length | SOME/IP Header | SD ]</code> als Multicast/Unicast auf das Netzwerk.\n</li></ul>\n</li><li><strong>Payload-Serialisierung &amp; Übertragung (Datenpfad):</strong>\n<ul class=\"fig-list\"><li>Die SWC übergibt <code>dataZ1</code> an den RTE-P-Port.\n</li><li>Der <code>Serializer Transformer</code> serialisiert die Datenstruktur und injiziert den SOME/IP-Header.\n</li><li>Die PDU passiert <code>LdCom</code>, den nun aktiven <code>PduR</code> und <code>SoAd</code>.\n</li><li><code>SoAd</code> versieht die PDU mit dem Längenfeld und übermittelt sie via IP/Ethernet an Abonnenten.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>TPS_SWCT_01560 / TPS_SWCT_01561:</strong> Die Freigabe eines SOME/IP-Dienstes darf nicht statisch beim ECU-Start erfolgen, wenn der Dienst von signalbasierten Quellwerten abhängt. Die Translation SWC muss explizit den semantischen Gültigkeitsstatus an das BSW melden, um inkonsistente / undefinierte Initialdaten auf dem Ethernet-Bus zu verhindern.\n</li><li><strong>PduR Routing Path Groups (<code>PduRRoutingPathGroup</code>):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen die <code>PduRRoutingPathGroup</code> für die Event-/Method-PDUs exakt der jeweiligen Server-Service-Instanz im SD zuordnen (<code>SdRoutingPathGroupRef</code>).\n</li><li>Fehlkonfiguration führt dazu, dass PDUs bereits vor dem SD-Offer gesendet und vom PduR verworfen werden oder nach Dienstverlust nicht sauber gestoppt werden.\n</li></ul>\n</li><li><strong>Einsatz von <code>LdCom</code> statt <code>Com</code>:</strong>\n<ul class=\"fig-list\"><li>Für transformierte Datenelemente (<code>ISignalIPdu</code> mit SOME/IP Transformer) ist <code>LdCom</code> zu konfigurieren. <code>LdCom</code> umgeht das signalbasierte IPDU-Buffering und Signal-Parsing des klassischen AUTOSAR <code>Com</code>-Moduls, was CPU-Overhead und Latenz drastisch reduziert.\n</li></ul>\n</li><li><strong>Fehlerbehandlung &amp; Timeouts (ASR Stack):</strong>\n<ul class=\"fig-list\"><li>Fällt ein signalbasierter Input weg (z. B. CAN-Timeout über Dead-Line Monitoring), muss die Translation SWC den Zustand <code>Service available = FALSE</code> an den BswM melden.\n</li><li>Der BswM veranlasst <code>SD</code> zum Senden eines <code>StopOfferService</code> und zum Aufruf von <code>PduR_DisableRouting()</code>.\n</li></ul>\n</li></ul>"}, {"id": "FIG-baf0dcc363043925", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Technisches Architektur- und Interaktionsdiagramm (Mischform aus AUTOSAR-Schichtenmodell, Funktions- und PDU-Datenfluss sowie Kontrollfluss zur Dienstverwaltung).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Kopplung zwischen signalbasierter Legacy-Kommunikation (z. B. CAN/LIN/FlexRay) und serviceorientierter Ethernet-Kommunikation (SOME/IP). Dargestellt wird die signal-zu-dienst-übersetzende Software-Komponente (<strong>Translation SWC</strong>) sowie deren Interaktion mit dem <strong>Basic Software Manager (BswM)</strong>, dem <strong>SOME/IP Service Discovery (SD)</strong> und dem <strong>PduR-Routingpfad-Management</strong> zur kontrollierten Dienstfreigabe.\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (R19-11, R20-11, TPS_SystemTemplate). Verortung an der Grenze zwischen VFB/RTE-Ebene (Applikation/Translation SWC, Transformer) und BSW-Kommunikationsstack (<code>LdCom</code>, <code>PduR</code>, <code>SoAd</code>, <code>SD</code>, <code>BswM</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Software-Komponenten &amp; VFB (Applikationsebene)</h5>\n<ul class=\"fig-list\"><li><strong>Translation SWC</strong> (<code>AtomicSwComponentType</code>):\n<ul class=\"fig-list\"><li><strong>R-Ports</strong> (<code>RPortPrototype</code>): Empfang signalbasierter Eingangs-PDUs (<code>PDU [A | C]</code> und <code>PDU [B]</code>).\n</li><li><strong>P-Port (Data)</strong> (<code>PPortPrototype</code>): Typisiert durch <code>SenderReceiverInterface ifZ</code> mit den Datenelementen <code>dataZ1 {A, C}</code> und <code>dataZ2 {B}</code>.\n</li><li><strong>P-Port (Control)</strong> (<code>PPortPrototype</code>): Meldet Dienstverfügbarkeit (<code>Service available</code>) an das BSW.\n</li></ul>\n</li><li><strong>Serializer Transformer</strong> (<code>TransformationTechnology</code>, SOME/IP-Transformer):\n<ul class=\"fig-list\"><li>Arbeitet in der RTE-Transformatorkette.\n</li><li>Serialisiert strukturierte Daten (<code>dataZ1</code>) und stellt den 16-Byte <strong>SOME/IP-Header</strong> voran.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Basis-Software-Module (BSW)</h5>\n<ul class=\"fig-list\"><li><strong>BswM</strong> (<em>Basic Software Manager</em>):\n<ul class=\"fig-list\"><li>Empfängt Statusinformationen über <code>BswMModeRequestPort</code> bzw. BSW-Service-Schnittstelle.\n</li><li>Evaluiert Arbitrierungsregeln (<code>BswMRule</code>) zur Dienstaktivierung.\n</li></ul>\n</li><li><strong>SD</strong> (<em>SOME/IP Service Discovery</em>):\n<ul class=\"fig-list\"><li>Verwaltet den Server-Dienstzustand (<code>SdServerServiceInstance</code>).\n</li><li>Triggert PduR-Routing-Freigabe und sendet SD-Offer-Nachrichten.\n</li></ul>\n</li><li><strong>LdCom</strong> (<em>Large Data Communication</em>):\n<ul class=\"fig-list\"><li>Schlankes Kommunikationsmodul für große, bereits serialisierte PDUs (Umgehung des klassischen COM-Signalpackens).\n</li></ul>\n</li><li><strong>PduR</strong> (<em>PDU Router</em>):\n<ul class=\"fig-list\"><li>Leitet I-PDUs zwischen Quell- und Zielmodulen (<code>LdCom</code> → <code>SoAd</code>).\n</li><li>Besitzt dynamisch schaltbare Routingpfade (<code>PduRRoutingPathGroup</code>).\n</li></ul>\n</li><li><strong>SoAd</strong> (<em>Socket Adaptor</em>):\n<ul class=\"fig-list\"><li>Schnittstelle zum TCP/IP-Stack; zuständig für Socket-Verwaltung, PDU-Fan-out und Protokollkapselung (z. B. <code>Message Length</code> Header).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">PDU- und Nachrichtenstrukturen</h5>\n<ul class=\"fig-list\"><li><strong>Signal-PDUs:</strong> Klassische Payload ohne SOME/IP-Framing (<code>[ A | C ]</code>, <code>[ B ]</code>).\n</li><li><strong>Transformierte I-PDU:</strong> <code>[ SOME/IP Header | A | C ]</code> (am Ausgang des Transformers und durch <code>LdCom</code>/<code>PduR</code>).\n</li><li><strong>Egress-Ethernet-PDU (Data):</strong> <code>[ Message Length | SOME/IP Header | A | C ]</code> (via <code>SoAd</code>).\n</li><li><strong>Egress-Ethernet-PDU (SD):</strong> <code>[ Message Length | SOME/IP Header | SD Payload ]</code> (SD Offer Service Message).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei synchron/asynchron gekoppelte Pfade: Kontrollpfad (Dienstverfügbarkeit) und Datenpfad (Payload-Übertragung).</p>\n<pre class=\"fig-pre\"><code>[Signal-PDUs] ---&gt; (Translation SWC) ---[Service available]---&gt; (BswM)\n                         |                                         |\n                         | (dataZ1)                             (offer)\n                         v                                         v\n                [Serializer Transf.]                              (SD)\n                         |                                      /      \\\n                      (LdCom)                     (enableRouting)     [SD Offer]\n                         |                              |                  |\n                         +-----&gt; (PduR [gesperrt -&gt; AKTIV])              (SoAd)\n                                       |                                   |\n                                    (SoAd)                            [ETH TX]\n                                       |\n                                    [ETH TX]</code></pre>\n<ol class=\"fig-list\"><li><strong>Signal-Empfang &amp; Aggregation:</strong> Die Translation SWC empfängt signalbasierte PDUs über klassische Busse, extrahiert die Signale <code>A</code> und <code>C</code> und aggregiert sie in <code>dataZ1</code>.\n</li><li><strong>Dienstzustandsprüfung:</strong> Sobald die Signale gültig und konsistent vorliegen, setzt die Translation SWC das Kontrollsignal <code>Service available</code> (synchroner RTE-Call / BswM-Port).\n</li><li><strong>BswM-Arbitrierung &amp; SD-Trigger:</strong>\n<ul class=\"fig-list\"><li><code>BswM</code> wertet die Bedingung aus.\n</li><li><code>BswM</code> führt eine Action-List aus und ruft <code>Sd_ServerServiceSetState(..., SD_SERVER_SERVICE_AVAILABLE)</code> auf (<strong>offer</strong>).\n</li></ul>\n</li><li><strong>PduR-Routingpfad-Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Das SD-Modul ruft <code>PduR_EnableRouting()</code> für die referenzierte <code>PduRRoutingPathGroup</code> auf (<strong>enableRouting</strong>).\n</li><li>Erst hierdurch wird der Routing-Pfad in <code>PduR</code> von <em>disabled</em> auf <em>enabled</em> geschaltet. Daten-PDUs vor diesem Zeitpunkt werden verworfen.\n</li></ul>\n</li><li><strong>Dienstpublikation (SOME/IP-SD):</strong>\n<ul class=\"fig-list\"><li>Parallel/unmittelbar folgend übergibt <code>SD</code> die Offer-Service-PDU an <code>SoAd</code>.\n</li><li><code>SoAd</code> sendet <code>[ Message Length | SOME/IP Header | SD ]</code> als Multicast/Unicast auf das Netzwerk.\n</li></ul>\n</li><li><strong>Payload-Serialisierung &amp; Übertragung (Datenpfad):</strong>\n<ul class=\"fig-list\"><li>Die SWC übergibt <code>dataZ1</code> an den RTE-P-Port.\n</li><li>Der <code>Serializer Transformer</code> serialisiert die Datenstruktur und injiziert den SOME/IP-Header.\n</li><li>Die PDU passiert <code>LdCom</code>, den nun aktiven <code>PduR</code> und <code>SoAd</code>.\n</li><li><code>SoAd</code> versieht die PDU mit dem Längenfeld und übermittelt sie via IP/Ethernet an Abonnenten.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>TPS_SWCT_01560 / TPS_SWCT_01561:</strong> Die Freigabe eines SOME/IP-Dienstes darf nicht statisch beim ECU-Start erfolgen, wenn der Dienst von signalbasierten Quellwerten abhängt. Die Translation SWC muss explizit den semantischen Gültigkeitsstatus an das BSW melden, um inkonsistente / undefinierte Initialdaten auf dem Ethernet-Bus zu verhindern.\n</li><li><strong>PduR Routing Path Groups (<code>PduRRoutingPathGroup</code>):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen die <code>PduRRoutingPathGroup</code> für die Event-/Method-PDUs exakt der jeweiligen Server-Service-Instanz im SD zuordnen (<code>SdRoutingPathGroupRef</code>).\n</li><li>Fehlkonfiguration führt dazu, dass PDUs bereits vor dem SD-Offer gesendet und vom PduR verworfen werden oder nach Dienstverlust nicht sauber gestoppt werden.\n</li></ul>\n</li><li><strong>Einsatz von <code>LdCom</code> statt <code>Com</code>:</strong>\n<ul class=\"fig-list\"><li>Für transformierte Datenelemente (<code>ISignalIPdu</code> mit SOME/IP Transformer) ist <code>LdCom</code> zu konfigurieren. <code>LdCom</code> umgeht das signalbasierte IPDU-Buffering und Signal-Parsing des klassischen AUTOSAR <code>Com</code>-Moduls, was CPU-Overhead und Latenz drastisch reduziert.\n</li></ul>\n</li><li><strong>Fehlerbehandlung &amp; Timeouts (ASR Stack):</strong>\n<ul class=\"fig-list\"><li>Fällt ein signalbasierter Input weg (z. B. CAN-Timeout über Dead-Line Monitoring), muss die Translation SWC den Zustand <code>Service available = FALSE</code> an den BswM melden.\n</li><li>Der BswM veranlasst <code>SD</code> zum Senden eines <code>StopOfferService</code> und zum Aufruf von <code>PduR_DisableRouting()</code>.\n</li></ul>\n</li></ul>"}, {"id": "FIG-95f740dc483ace3e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Technisches Architektur- und Interaktionsdiagramm (Mischform aus AUTOSAR-Schichtenmodell, Funktions- und PDU-Datenfluss sowie Kontrollfluss zur Dienstverwaltung).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Kopplung zwischen signalbasierter Legacy-Kommunikation (z. B. CAN/LIN/FlexRay) und serviceorientierter Ethernet-Kommunikation (SOME/IP). Dargestellt wird die signal-zu-dienst-übersetzende Software-Komponente (<strong>Translation SWC</strong>) sowie deren Interaktion mit dem <strong>Basic Software Manager (BswM)</strong>, dem <strong>SOME/IP Service Discovery (SD)</strong> und dem <strong>PduR-Routingpfad-Management</strong> zur kontrollierten Dienstfreigabe.\n</li><li><strong>Funktionale Einordnung:</strong> AUTOSAR Classic Platform (R25-11, TPS_SystemTemplate). Verortung an der Grenze zwischen VFB/RTE-Ebene (Applikation/Translation SWC, Transformer) und BSW-Kommunikationsstack (<code>Com</code>, <code>PduR</code>, <code>SoAd</code>, <code>SD</code>, <code>BswM</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Software-Komponenten &amp; VFB (Applikationsebene)</h5>\n<ul class=\"fig-list\"><li><strong>Translation SWC</strong> (<code>AtomicSwComponentType</code>):\n<ul class=\"fig-list\"><li><strong>R-Ports</strong> (<code>RPortPrototype</code>): Empfang signalbasierter Eingangs-PDUs (<code>PDU [A | C]</code> und <code>PDU [B]</code>).\n</li><li><strong>P-Port (Data)</strong> (<code>PPortPrototype</code>): Typisiert durch <code>SenderReceiverInterface ifZ</code> mit den Datenelementen <code>dataZ1 {A, C}</code> und <code>dataZ2 {B}</code>.\n</li><li><strong>P-Port (Control)</strong> (<code>PPortPrototype</code>): Meldet Dienstverfügbarkeit (<code>Service available</code>) an das BSW.\n</li></ul>\n</li><li><strong>Serializer Transformer</strong> (<code>TransformationTechnology</code>, SOME/IP-Transformer):\n<ul class=\"fig-list\"><li>Arbeitet in der RTE-Transformatorkette.\n</li><li>Serialisiert strukturierte Daten (<code>dataZ1</code>) und stellt den 16-Byte <strong>SOME/IP-Header</strong> voran.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Basis-Software-Module (BSW)</h5>\n<ul class=\"fig-list\"><li><strong>BswM</strong> (<em>Basic Software Manager</em>):\n<ul class=\"fig-list\"><li>Empfängt Statusinformationen über <code>BswMModeRequestPort</code> bzw. BSW-Service-Schnittstelle.\n</li><li>Evaluiert Arbitrierungsregeln (<code>BswMRule</code>) zur Dienstaktivierung.\n</li></ul>\n</li><li><strong>SD</strong> (<em>SOME/IP Service Discovery</em>):\n<ul class=\"fig-list\"><li>Verwaltet den Server-Dienstzustand (<code>SdServerServiceInstance</code>).\n</li><li>Triggert PduR-Routing-Freigabe und sendet SD-Offer-Nachrichten.\n</li></ul>\n</li><li><strong>Com</strong> (<em>AUTOSAR COM</em>):\n<ul class=\"fig-list\"><li>Klassisches Kommunikationsmodul, das hier die serialisierten PDUs aus dem Transformer entgegennimmt und an den PduR weiterleitet.\n</li></ul>\n</li><li><strong>PduR</strong> (<em>PDU Router</em>):\n<ul class=\"fig-list\"><li>Leitet I-PDUs zwischen Quell- und Zielmodulen (<code>Com</code> → <code>SoAd</code>).\n</li><li>Besitzt dynamisch schaltbare Routingpfade (<code>PduRRoutingPathGroup</code>).\n</li></ul>\n</li><li><strong>SoAd</strong> (<em>Socket Adaptor</em>):\n<ul class=\"fig-list\"><li>Schnittstelle zum TCP/IP-Stack; zuständig für Socket-Verwaltung, PDU-Fan-out und Protokollkapselung (z. B. <code>Message Length</code> Header).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">PDU- und Nachrichtenstrukturen</h5>\n<ul class=\"fig-list\"><li><strong>Signal-PDUs:</strong> Klassische Payload ohne SOME/IP-Framing (<code>[ A | C ]</code>, <code>[ B ]</code>).\n</li><li><strong>Transformierte I-PDU:</strong> <code>[ SOME/IP Header | A | C ]</code> (am Ausgang des Transformers und durch <code>Com</code>/<code>PduR</code>).\n</li><li><strong>Egress-Ethernet-PDU (Data):</strong> <code>[ Message Length | SOME/IP Header | A | C ]</code> (via <code>SoAd</code>).\n</li><li><strong>Egress-Ethernet-PDU (SD):</strong> <code>[ Message Length | SOME/IP Header | SD Payload ]</code> (SD Offer Service Message).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in zwei synchron/asynchron gekoppelte Pfade: Kontrollpfad (Dienstverfügbarkeit) und Datenpfad (Payload-Übertragung).</p>\n<pre class=\"fig-pre\"><code>[Signal-PDUs] ---&gt; (Translation SWC) ---[Service available]---&gt; (BswM)\n                         |                                         |\n                         | (dataZ1)                             (offer)\n                         v                                         v\n                [Serializer Transf.]                              (SD)\n                         |                                      /      \\\n                       (Com)                      (enableRouting)     [SD Offer]\n                         |                              |                  |\n                         +-----&gt; (PduR [gesperrt -&gt; AKTIV])              (SoAd)\n                                       |                                   |\n                                    (SoAd)                            [ETH TX]\n                                       |\n                                    [ETH TX]</code></pre>\n<ol class=\"fig-list\"><li><strong>Signal-Empfang &amp; Aggregation:</strong> Die Translation SWC empfängt signalbasierte PDUs über klassische Busse, extrahiert die Signale <code>A</code> und <code>C</code> und aggregiert sie in <code>dataZ1</code>.\n</li><li><strong>Dienstzustandsprüfung:</strong> Sobald die Signale gültig und konsistent vorliegen, setzt die Translation SWC das Kontrollsignal <code>Service available</code> (synchroner RTE-Call / BswM-Port).\n</li><li><strong>BswM-Arbitrierung &amp; SD-Trigger:</strong>\n<ul class=\"fig-list\"><li><code>BswM</code> wertet die Bedingung aus.\n</li><li><code>BswM</code> führt eine Action-List aus und ruft <code>Sd_ServerServiceSetState(..., SD_SERVER_SERVICE_AVAILABLE)</code> auf (<strong>offer</strong>).\n</li></ul>\n</li><li><strong>PduR-Routingpfad-Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Das SD-Modul ruft <code>PduR_EnableRouting()</code> für die referenzierte <code>PduRRoutingPathGroup</code> auf (<strong>enableRouting</strong>).\n</li><li>Erst hierdurch wird der Routing-Pfad in <code>PduR</code> von <em>disabled</em> auf <em>enabled</em> geschaltet. Daten-PDUs vor diesem Zeitpunkt werden verworfen.\n</li></ul>\n</li><li><strong>Dienstpublikation (SOME/IP-SD):</strong>\n<ul class=\"fig-list\"><li>Parallel/unmittelbar folgend übergibt <code>SD</code> die Offer-Service-PDU an <code>SoAd</code>.\n</li><li><code>SoAd</code> sendet <code>[ Message Length | SOME/IP Header | SD ]</code> als Multicast/Unicast auf das Netzwerk.\n</li></ul>\n</li><li><strong>Payload-Serialisierung &amp; Übertragung (Datenpfad):</strong>\n<ul class=\"fig-list\"><li>Die SWC übergibt <code>dataZ1</code> an den RTE-P-Port.\n</li><li>Der <code>Serializer Transformer</code> serialisiert die Datenstruktur und injiziert den SOME/IP-Header.\n</li><li>Die PDU passiert <code>Com</code>, den nun aktiven <code>PduR</code> und <code>SoAd</code>.\n</li><li><code>SoAd</code> versieht die PDU mit dem Längenfeld und übermittelt sie via IP/Ethernet an Abonnenten.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>TPS_SWCT_01560 / TPS_SWCT_01561:</strong> Die Freigabe eines SOME/IP-Dienstes darf nicht statisch beim ECU-Start erfolgen, wenn der Dienst von signalbasierten Quellwerten abhängt. Die Translation SWC muss explizit den semantischen Gültigkeitsstatus an das BSW melden, um inkonsistente / undefinierte Initialdaten auf dem Ethernet-Bus zu verhindern.\n</li><li><strong>PduR Routing Path Groups (<code>PduRRoutingPathGroup</code>):</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen die <code>PduRRoutingPathGroup</code> für die Event-/Method-PDUs exakt der jeweiligen Server-Service-Instanz im SD zuordnen (<code>SdRoutingPathGroupRef</code>).\n</li><li>Fehlkonfiguration führt dazu, dass PDUs bereits vor dem SD-Offer gesendet und vom PduR verworfen werden oder nach Dienstverlust nicht sauber gestoppt werden.\n</li></ul>\n</li><li><strong>Einsatz von <code>Com</code>:</strong>\n<ul class=\"fig-list\"><li>In dieser Spezifikationsfassung wird die transformierte I-PDU (<code>ISignalIPdu</code> mit SOME/IP Transformer) über das <code>Com</code>-Modul anstelle von <code>LdCom</code> in den BSW-Stack eingespeist. Die COM-Konfiguration muss für die Weiterleitung der vor-serialisierten I-PDU an den PduR ausgelegt sein.\n</li></ul>\n</li><li><strong>Fehlerbehandlung &amp; Timeouts (ASR Stack):</strong>\n<ul class=\"fig-list\"><li>Fällt ein signalbasierter Input weg (z. B. CAN-Timeout über Dead-Line Monitoring), muss die Translation SWC den Zustand <code>Service available = FALSE</code> an den BswM melden.\n</li><li>Der BswM veranlasst <code>SD</code> zum Senden eines <code>StopOfferService</code> und zum Aufruf von <code>PduR_DisableRouting()</code>.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-cc5814ea2c90d29f", "to": "FIG-baf0dcc363043925", "fr": "R20-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung <code>Service available</code>: Schriftfarbe von Rot auf Violett geändert.\n</li><li>Komponentenbox <code>Translation SWC</code>: Schattenwurf im Diagrammlayout von rechts unten nach links unten versetzt.\n</li></ul>"}, {"from": "FIG-baf0dcc363043925", "to": "FIG-95f740dc483ace3e", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>BSW-Modul <code>LdCom</code>: Ersetzt durch <code>Com</code> (AUTOSAR COM) als Vermittlungsinstanz zwischen <code>Serializer Transformer</code> und <code>PduR</code> im Datenpfad.\n</li><li>Beschriftung <code>Service available</code>: Schriftfarbe von Violett wieder auf Rot zurückgesetzt (einheitliche Farbgebung des Dienststeuer- und Freigabepfads).\n</li><li>Komponentenbox <code>Translation SWC</code>: Schattenwurf wieder nach rechts unten ausgerichtet.\n</li></ul>"}]};
